namespace Mes.Api.Data;

public abstract class Row { public Guid Id { get; set; } = Guid.NewGuid(); }
public class User : Row { public string Account { get; set; } = ""; public string Name { get; set; } = ""; public string PasswordHash { get; set; } = ""; public string Role { get; set; } = "Operator"; public bool Active { get; set; } = true; public int FailedLogins { get; set; } public DateTimeOffset? LockedUntil { get; set; } }
public class StationCredential : Row { public Guid UserId { get; set; } public string TokenHash { get; set; } = ""; public DateTimeOffset Expires { get; set; } }
public class Session : Row { public Guid? StationCredentialId { get; set; } public Guid UserId { get; set; } public string TokenHash { get; set; } = ""; public DateTimeOffset Expires { get; set; } }
public class Line : Row { public string Code { get; set; } = ""; public string Name { get; set; } = ""; public string Workshop { get; set; } = ""; }
public class ProcessStep : Row { public int Sequence { get; set; } public string Name { get; set; } = ""; }
public class Station : Row { public string Code { get; set; } = ""; public string Name { get; set; } = ""; public Guid LineId { get; set; } public Guid ProcessStepId { get; set; } public DateTimeOffset? LastSeen { get; set; } }
public class StationGrant : Row { public Guid UserId { get; set; } public Guid StationId { get; set; } }
public class RolePermission : Row { public string Role { get; set; }=""; public string Permission { get; set; }=""; }
public class Product : Row { public string Code { get; set; } = ""; public string Name { get; set; } = ""; }
public class WorkOrder : Row { public string Code { get; set; } = ""; public Guid ProductId { get; set; } public Guid LineId { get; set; } public int Plan { get; set; } public string Status { get; set; } = "Open"; }
public class Batch : Row { public string Code { get; set; } = ""; public Guid WorkOrderId { get; set; } public int Plan { get; set; } }
public class Unit : Row { public Guid BatchId { get; set; } public string MainCode { get; set; } = ""; public string? CellCode { get; set; } public string? SnCode { get; set; } public string? PackCode { get; set; } public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow; }
public class BarcodeRule : Row { public string Kind { get; set; } = ""; public int Version { get; set; } public string[] Prefixes { get; set; } = []; public int Length { get; set; } public string Charset { get; set; } = "alnum"; public DateTimeOffset PublishedAt { get; set; } = DateTimeOffset.UtcNow; }
public class Passage : Row { public Guid UnitId { get; set; } public Guid StationId { get; set; } public Guid ProcessStepId { get; set; } public Guid? UserId { get; set; } public Guid? SopVersionId { get; set; } public Guid? BarcodeRuleId { get; set; } public DateTimeOffset At { get; set; } = DateTimeOffset.UtcNow; }
public class ScanContext : Row { public Guid UserId { get; set; } public Guid StationId { get; set; } public Guid BatchId { get; set; } public Guid? UnitId { get; set; } public DateTimeOffset Expires { get; set; } }
public class ScanRequest : Row { public Guid UserId { get; set; } public Guid RequestId { get; set; } public string Hash { get; set; } = ""; public string Response { get; set; } = ""; }
public class Device : Row { public string Code { get; set; } = ""; public string Name { get; set; } = ""; public Guid StationId { get; set; } public string KeyHash { get; set; } = ""; public bool Active { get; set; } = true; public DateTimeOffset? LastSeen { get; set; } public string Protocol { get; set; } = "generic-v1"; public string ProgramVersion { get; set; } = ""; public string RequiredItems { get; set; } = "[]"; }
public class TestTask : Row { public Guid? SopVersionId { get; set; } public Guid UnitId { get; set; } public Guid DeviceId { get; set; } public Guid StationId { get; set; } public Guid BatchId { get; set; } public string ExternalId { get; set; } = ""; public string ProgramVersion { get; set; } = ""; public string Specification { get; set; } = "[]"; public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow; public long Sequence { get; set; } public string Status { get; set; } = "Pending"; }
public class TestResult : Row { public Guid TestTaskId { get; set; } public Guid DeviceId { get; set; } public string RecordId { get; set; } = ""; public DateTimeOffset TestedAt { get; set; } public DateTimeOffset ReceivedAt { get; set; } = DateTimeOffset.UtcNow; public string Verdict { get; set; } = ""; public string PayloadHash { get; set; } = ""; public string Raw { get; set; } = ""; }
public class TestItem : Row { public Guid TestResultId { get; set; } public string Name { get; set; } = ""; public decimal Value { get; set; } public string Unit { get; set; } = ""; public decimal Lower { get; set; } public decimal Upper { get; set; } public string Verdict { get; set; } = ""; }
public class Receipt : Row { public Guid DeviceId { get; set; } public string Operation { get; set; } = ""; public string RecordId { get; set; } = ""; public string Raw { get; set; } = ""; public string Status { get; set; } = ""; public string Reason { get; set; } = ""; public DateTimeOffset At { get; set; } = DateTimeOffset.UtcNow; }
public class SopVersion : Row { public Guid ProcessStepId { get; set; } public int Version { get; set; } public string Title { get; set; } = ""; public string Status { get; set; } = "Draft"; public Guid CreatedBy { get; set; } public Guid? ReviewedBy { get; set; } public DateTimeOffset? PublishedAt { get; set; } }
public class SopFile : Row { public Guid SopVersionId { get; set; } public string Name { get; set; } = ""; public string StorageName { get; set; } = ""; public string ContentType { get; set; } = ""; public string Sha256 { get; set; } = ""; public int Position { get; set; } public int Seconds { get; set; } = 10; public long Size { get; set; } }
public class Message : Row { public string Title { get; set; } = ""; public string Body { get; set; } = ""; public Guid? LineId { get; set; } public bool Important { get; set; } public Guid CreatedBy { get; set; } public DateTimeOffset At { get; set; } = DateTimeOffset.UtcNow; }
public class MessageAck : Row { public Guid MessageId { get; set; } public Guid UserId { get; set; } public DateTimeOffset At { get; set; } = DateTimeOffset.UtcNow; }
public class Audit : Row { public Guid? UserId { get; set; } public string Action { get; set; } = ""; public string Detail { get; set; } = ""; public string Outcome { get; set; } = ""; public DateTimeOffset At { get; set; } = DateTimeOffset.UtcNow; }
public class ExportJob : Row { public Guid UserId { get; set; } public Guid WorkOrderId { get; set; } public Guid BatchId { get; set; } public string Kind { get; set; } = ""; public string Filter { get; set; } = ""; public string Status { get; set; } = "Queued"; public string? FileName { get; set; } public string? Error { get; set; } public DateTimeOffset At { get; set; } = DateTimeOffset.UtcNow; }
public class BackupJob : Row { public Guid? UserId { get; set; } public string Status { get; set; } = "Queued"; public string? FileName { get; set; } public string? Error { get; set; } public DateTimeOffset At { get; set; } = DateTimeOffset.UtcNow; }
public class Setting : Row { public string Key { get; set; } = ""; public string Value { get; set; } = ""; }
